/* John Class — 全站音效 · audio.js */
(function(){
  const BGM_SRC = "data:audio/mp3;base64,";
  const BGM_VOL = 0.12;

  /* ── 点击音 ── */
  let _ac = null;
  function getAC(){
    if(!_ac) _ac = new (window.AudioContext||window.webkitAudioContext)();
    return _ac;
  }
  function playClick(){
    try{
      const ac = getAC();
      const osc = ac.createOscillator();
      const env = ac.createGain();
      osc.type = "sine";
      osc.frequency.value = 820;
      env.gain.setValueAtTime(0.18, ac.currentTime);
      env.gain.exponentialRampToValueAtTime(0.001, ac.currentTime + 0.09);
      osc.connect(env); env.connect(ac.destination);
      osc.start(ac.currentTime); osc.stop(ac.currentTime + 0.09);
    }catch(e){}
  }

  /* ── 背景音乐 ── */
  let bgm = null;
  let muted = localStorage.getItem("jc_muted") === "1";
  let started = false;

  function initBGM(){
    if(bgm) return;
    bgm = new Audio(BGM_SRC);
    bgm.loop = true;
    bgm.volume = muted ? 0 : BGM_VOL;

    // 恢复上次播放位置，实现跨页面连续
    const saved = sessionStorage.getItem("jc_bgm_pos");
    if(saved) bgm.currentTime = parseFloat(saved) || 0;

    // 页面卸载前保存进度
    window.addEventListener("pagehide", ()=>{
      if(bgm) sessionStorage.setItem("jc_bgm_pos", bgm.currentTime);
    });
    window.addEventListener("beforeunload", ()=>{
      if(bgm) sessionStorage.setItem("jc_bgm_pos", bgm.currentTime);
    });
  }

  function startBGM(){
    if(started) return;
    started = true;
    initBGM();
    bgm.play().catch(()=>{});
  }

  function toggleMute(){
    muted = !muted;
    if(bgm) bgm.volume = muted ? 0 : BGM_VOL;
    const btn = document.getElementById("jc-mute-btn");
    if(btn) btn.textContent = muted ? "🔇" : "🔉";
    localStorage.setItem("jc_muted", muted ? "1" : "0");
  }

  /* ── 悬浮按钮 ── */
  function injectBtn(){
    if(document.getElementById("jc-mute-btn")) return;
    const btn = document.createElement("button");
    btn.id = "jc-mute-btn";
    btn.textContent = muted ? "🔇" : "🔉";
    btn.title = "背景音乐开关";
    btn.style.cssText = `
      position:fixed;bottom:22px;right:22px;z-index:9999;
      width:38px;height:38px;border-radius:50%;
      background:rgba(255,255,255,.18);backdrop-filter:blur(8px);
      border:1px solid rgba(255,255,255,.25);
      font-size:16px;cursor:pointer;
      transition:transform .15s,background .15s;
      display:flex;align-items:center;justify-content:center;
      box-shadow:0 2px 12px rgba(0,0,0,.12);
    `;
    btn.onmouseenter = ()=>{ btn.style.transform="scale(1.12)"; btn.style.background="rgba(255,255,255,.3)"; };
    btn.onmouseleave = ()=>{ btn.style.transform=""; btn.style.background="rgba(255,255,255,.18)"; };
    btn.onclick = ()=>{ playClick(); toggleMute(); };
    document.body.appendChild(btn);
  }

  /* ── 绑定点击音 ── */
  function bindClicks(){
    document.addEventListener("click", e=>{
      const t = e.target.closest("button,a,.entry,.tool-item,.hub-card,.sub-item,.set-btn,.grade-btn,.btn,.opt,.tip,.f-node");
      if(t) playClick();
    }, true);
  }

  /* ── 首次交互后启动 ── */
  function onFirstInteract(){
    startBGM();
    document.removeEventListener("click", onFirstInteract);
    document.removeEventListener("keydown", onFirstInteract);
    document.removeEventListener("touchstart", onFirstInteract);
  }
  document.addEventListener("click", onFirstInteract);
  document.addEventListener("keydown", onFirstInteract);
  document.addEventListener("touchstart", onFirstInteract);

  if(document.readyState === "loading"){
    document.addEventListener("DOMContentLoaded", ()=>{ injectBtn(); bindClicks(); });
  } else {
    injectBtn(); bindClicks();
  }
})();
